      CASE WHEN d.state='live' THEN (SELECT COALESCE(SUM(MAX(0,t.size-COALESCE(p.published_offset,0))),0) FROM transcripts t LEFT JOIN transcript_publication p ON p.project_id=t.project_id
    AND p.transcript_id=t.transcript_id AND p.generation=d.generation WHERE t.project_id=d.project_id AND t.session_id=d.session_id) ELSE 0 END,
      EXISTS(SELECT 1 FROM transcripts t WHERE t.project_id=d.project_id AND t.session_id=d.session_id)
        AND NOT EXISTS(SELECT 1 FROM transcripts t WHERE t.project_id=d.project_id AND t.session_id=d.session_id AND t.imported_at IS NULL),
      CASE WHEN d.state='live' AND json_valid(d.build) THEN COALESCE(json_extract(d.build,'$.report.classes'),'{}') ELSE '{}' END
    FROM session_documents d WHERE d.project_id=NEW.project_id AND d.session_id=NEW.session_id
  ON CONFLICT(project_id,session_id) DO UPDATE SET state=excluded.state,due_at=excluded.due_at,
    transcripts=excluded.transcripts,bytes=excluded.bytes,imported=excluded.imported,classes=excluded.classes
  WHERE document_publication_facts.state IS NOT excluded.state OR document_publication_facts.due_at IS NOT excluded.due_at OR document_publication_facts.transcripts IS NOT excluded.transcripts OR document_publication_facts.bytes IS NOT excluded.bytes OR document_publication_facts.imported IS NOT excluded.imported OR document_publication_facts.classes IS NOT excluded.classes; END;

CREATE TRIGGER IF NOT EXISTS transcript_publication_facts_delete AFTER DELETE ON transcript_publication
      BEGIN INSERT INTO document_publication_facts(project_id,session_id,state,due_at,transcripts,bytes,imported,classes)
  SELECT d.project_id,d.session_id,d.state,d.due_at,
      CASE WHEN d.state='live' THEN (SELECT COUNT(*) FROM transcripts t LEFT JOIN transcript_publication p ON p.project_id=t.project_id
    AND p.transcript_id=t.transcript_id AND p.generation=d.generation WHERE t.project_id=d.project_id AND t.session_id=d.session_id AND COALESCE(p.published_offset,0)<t.size) ELSE 0 END,
      CASE WHEN d.state='live' THEN (SELECT COALESCE(SUM(MAX(0,t.size-COALESCE(p.published_offset,0))),0) FROM transcripts t LEFT JOIN transcript_publication p ON p.project_id=t.project_id
    AND p.transcript_id=t.transcript_id AND p.generation=d.generation WHERE t.project_id=d.project_id AND t.session_id=d.session_id) ELSE 0 END,
      EXISTS(SELECT 1 FROM transcripts t WHERE t.project_id=d.project_id AND t.session_id=d.session_id)
        AND NOT EXISTS(SELECT 1 FROM transcripts t WHERE t.project_id=d.project_id AND t.session_id=d.session_id AND t.imported_at IS NULL),
      CASE WHEN d.state='live' AND json_valid(d.build) THEN COALESCE(json_extract(d.build,'$.report.classes'),'{}') ELSE '{}' END
    FROM session_documents d WHERE d.project_id=OLD.project_id AND d.session_id=OLD.session_id
  ON CONFLICT(project_id,session_id) DO UPDATE SET state=excluded.state,due_at=excluded.due_at,
    transcripts=excluded.transcripts,bytes=excluded.bytes,imported=excluded.imported,classes=excluded.classes
  WHERE document_publication_facts.state IS NOT excluded.state OR document_publication_facts.due_at IS NOT excluded.due_at OR document_publication_facts.transcripts IS NOT excluded.transcripts OR document_publication_facts.bytes IS NOT excluded.bytes OR document_publication_facts.imported IS NOT excluded.imported OR document_publication_facts.classes IS NOT excluded.classes; END;

CREATE TRIGGER IF NOT EXISTS publish_queue_facts_insert AFTER INSERT ON publish_queue BEGIN
      UPDATE document_status_totals SET queued=queued+1; END;

CREATE TRIGGER IF NOT EXISTS publish_queue_facts_delete AFTER DELETE ON publish_queue BEGIN
      UPDATE document_status_totals SET queued=queued-1; END;

CREATE TRIGGER IF NOT EXISTS retired_objects_facts_insert AFTER INSERT ON retired_objects BEGIN
      UPDATE document_status_totals SET retired=retired+1; END;

CREATE TRIGGER IF NOT EXISTS retired_objects_facts_delete AFTER DELETE ON retired_objects BEGIN
      UPDATE document_status_totals SET retired=retired-1; END;

CREATE TABLE IF NOT EXISTS _document_fact_range(high INTEGER NOT NULL);

INSERT INTO _document_fact_range SELECT COALESCE(MAX(rowid),0) FROM session_documents;

